package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Bounded read projection. Inventory receipts are fetched once; cached returns never query or mutate WMS. */
@Service public class RefundDispositionService {
    @Resource RefundService refunds;
    @Resource OrderWarehouseClient inventory;
    @Resource RefundLogisticsView logistics;
    private OrderRepository r(){return refunds.repository;}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> rows(Object raw){
        if(!(raw instanceof Collection))return Collections.emptyList();List<Map<String,Object>> out=new ArrayList<>();
        for(Object value:(Collection<?>)raw)if(value instanceof Map)out.add(new LinkedHashMap<>((Map<String,Object>)value));return out;
    }
    private static List<Map<String,Object>> commands(Map<String,Object> command){return command.get("requests") instanceof List?rows(command.get("requests")):command.isEmpty()?Collections.emptyList():Collections.singletonList(command);}
    public Map<String,Object> report(String c,long id){
        Map<String,Object> b=refunds.business(c,id,false);
        String meta="ol.platform_oid,ol.sku_sn,ol.goods_name,ol.bundle_id,ol.gift_plan_id,IF(ol.stocked_bundle_snapshot IS NULL,'件','套') stock_unit";
        List<Map<String,Object>> tasks=r().db().query("SELECT t.*,"+meta+" FROM oms_refund_goods_task t JOIN oms_order_line ol ON ol.company_code=t.company_code AND ol.id=t.order_line_id AND ol.order_id=t.order_id WHERE t.company_code=? AND t.refund_id=? AND t.order_id=? ORDER BY t.id LIMIT 201",ROW,c,id,b.get("order_id"));
        boolean truncated=tasks.size()>200;if(truncated)tasks.remove(tasks.size()-1);
        if(!"MIXED".equals(text(b,"goods_action"))&&(number(b,"cancel_quantity")>0||b.get("cancel_command")!=null)){
            List<Map<String,Object>> line=r().db().query("SELECT id order_line_id,"+meta+" FROM oms_order_line ol WHERE ol.company_code=? AND ol.order_id=? AND ol.id=?",ROW,c,b.get("order_id"),b.get("cancel_line_id"));
            if(!line.isEmpty()){Map<String,Object> t=line.get(0);t.putAll(m("id","single","action","CANCEL","quantity",b.get("cancel_quantity"),"state","DONE".equals(text(b,"goods_state"))?"DONE":"PENDING","command_json",b.get("cancel_command"),"cutoff_id",b.get("cutoff_id"),"create_time",b.get("reviewed_at"),"result_message",b.get("problem_message")));tasks.add(t);}}
        List<Map<String,Object>> plans=r().db().query("SELECT p.* FROM oms_refund_return_plan p WHERE p.company_code=? AND p.refund_id=? ORDER BY p.id LIMIT 201",ROW,c,id);
        if(plans.size()>200){plans.remove(plans.size()-1);truncated=true;}
        RefundReturnPresentation.sources(r(),c,plans,"shipment_line_id");
        List<Map<String,Object>> sources=r().db().query("SELECT sl.id shipment_line_id,sl.shipment_id,sl.order_line_id,sl.allocation_id,sl.sku_sn,sl.goods_name,sl.store_code,sl.quantity,sl.shipped_quantity,sh.shipment_sn,sh.real_store_name,ol.gift_plan_id,IF(ol.stocked_bundle_snapshot IS NULL,'件','套') stock_unit FROM oms_order_shipment_line sl JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id JOIN oms_order_line ol ON ol.company_code=sl.company_code AND ol.id=sl.order_line_id WHERE sl.company_code=? AND sh.order_id=? ORDER BY sl.id LIMIT 2001",ROW,c,b.get("order_id"));
        if(sources.size()>2000){sources.remove(sources.size()-1);truncated=true;}
        Map<Long,Map<String,Object>> sourceById=new HashMap<>();for(Map<String,Object> source:sources)sourceById.put(number(source,"shipment_line_id"),source);
        Set<Long> cutoffIds=new LinkedHashSet<>();List<String> requestIds=new ArrayList<>();
        for(Map<String,Object> task:tasks){Map<String,Object> command=obj(task.get("command_json"));if(!text(command,"request_id").isEmpty())requestIds.add(text(command,"request_id"));if(number(task,"cutoff_id")>0)cutoffIds.add(number(task,"cutoff_id"));}
        List<Map<String,Object>> cutoffItems=new ArrayList<>();
        if(!cutoffIds.isEmpty()){List<Object> args=new ArrayList<>(Arrays.asList(c,b.get("order_id")));args.addAll(cutoffIds);cutoffItems=r().db().query("SELECT i.*,o.mode,o.operator_name,o.create_time started_at,o.completed_at,d.id dispatch_id FROM oms_order_cutoff_item i JOIN oms_order_cutoff o ON o.company_code=i.company_code AND o.id=i.cutoff_id LEFT JOIN oms_order_shipment_dispatch d ON d.company_code=i.company_code AND d.shipment_id=i.shipment_id WHERE i.company_code=? AND o.order_id=? AND i.cutoff_id IN ("+String.join(",",Collections.nCopies(cutoffIds.size(),"?"))+") ORDER BY i.id LIMIT 1001",ROW,args.toArray());if(cutoffItems.size()>1000){cutoffItems.remove(cutoffItems.size()-1);truncated=true;}}
        Map<String,Map<String,Object>> receipts=new HashMap<>();String receiptIssue="";
        if(!requestIds.isEmpty())try{for(Map<String,Object> receipt:data(inventory.adjustmentReceipts(c,requestIds,SecurityConstants.INNER)))receipts.put(text(receipt,"request_id"),receipt);}catch(RuntimeException unavailable){receiptIssue="库存原回执暂未取到；保留任务记录，数量待核对，不会执行库存操作。";}
        List<Map<String,Object>> cancellations=new ArrayList<>(),returns=new ArrayList<>();Set<Long> planIds=new HashSet<>();
        for(Map<String,Object> p:plans){planIds.add(number(p,"id"));returns.add(returnResult(p,sourceById.get(number(p,"shipment_line_id"))));}
        for(Map<String,Object> task:tasks){if("CANCEL".equals(text(task,"action"))){Map<String,Object> command=obj(task.get("command_json"));cancellations.add(cancelResult(task,receipts.get(text(command,"request_id")),cutoffItems,sources));}
            else if(!planIds.contains(number(task,"return_plan_id"))){Map<String,Object> row=identity(task);Map<String,Object> source=sourceById.get(number(task,"shipment_line_id"));if(source!=null)row.putAll(m("shipment_id",source.get("shipment_id"),"shipment_sn",source.get("shipment_sn"),"original_store_code",source.get("store_code")));row.putAll(m("key","task-"+task.get("id"),"task_id",task.get("id"),"mode",task.get("action"),"state",task.get("state"),"quantity",task.get("quantity"),"accepted_quantity",0,"posted_quantity",0,"remaining_quantity",task.get("quantity"),"waived_quantity",0,"result_message",task.get("result_message"),"documents",Collections.emptyList(),"timeline",Collections.singletonList(m("title","追回任务已建立","time",task.get("create_time"),"actor","已审核分项任务","state",task.get("state"),"detail","退回安排尚未建立，实收与入库分别确认"))));returns.add(row);}}
        List<Map<String,Object>> operations=r().db().query("SELECT id,action,state,actor,result_message,create_time FROM oms_refund_operation WHERE company_code=? AND refund_id=? AND action IN ('CANCEL_FEEDBACK','INTERCEPT','INTERCEPT_FEEDBACK') ORDER BY id DESC LIMIT 30",ROW,c,id);
        List<Map<String,Object>> events=r().db().query("SELECT id,action,message,actor,create_time FROM oms_refund_event WHERE company_code=? AND refund_id=? AND action IN ('GOODS_SCOPE','SCOPE_CANCEL','AUTO_SCOPE_REPLAN','GOODS','GIFT_RETURN','RETURN_DOCUMENT','GOODS_COMPLETE','RETURN_AUTO_DISPATCH') ORDER BY id DESC LIMIT 100",ROW,c,id);
        Map<String,Object> logisticsView=logistics.read(c,b,plans,tasks,returns);
        return m("scope","REFUND","refund_id",id,"order_id",b.get("order_id"),"cancellations",cancellations,"returns",returns,"platform_operations",operations,"events",events,"receipt_issue",receiptIssue,"truncated",truncated,"goods_state",b.get("goods_state"),"goods_action",b.get("goods_action"),"logistics",logisticsView);
    }
    static Map<String,Object> identity(Map<String,Object> p){return m("sku_sn",p.get("sku_sn"),"goods_name",p.get("goods_name"),"stock_unit",p.get("stock_unit"),"item_kind",number(p,"gift_plan_id")>0?"GIFT":"PURCHASE","parent_goods_name",p.get("parent_goods_name"),"parent_sku_sn",p.get("parent_sku_sn"),"source_kind",p.get("source_kind"),"order_line_id",p.get("order_line_id"));}
    static Map<String,Object> cancelResult(Map<String,Object> task,Map<String,Object> receipt,List<Map<String,Object>> items,List<Map<String,Object>> sources){
        Map<String,Object> out=identity(task),command=obj(task.get("command_json"));boolean stopped="CANCELED".equals(text(task,"state"));
        List<Map<String,Object>> demands=rows(command.get("demands"));boolean commandMatches="REDUCE".equals(text(command,"mode"))&&demands.size()==1&&text(task,"platform_oid").equals(text(demands.get(0),"platform_oid"))&&text(task,"sku_sn").equals(text(demands.get(0),"sku_sn"))&&number(task,"quantity")==number(demands.get(0),"quantity");
        boolean valid=!stopped&&receipt!=null&&commandMatches&&"COMPLETED".equals(text(receipt,"state"))&&"REDUCE".equals(text(receipt,"mode"))&&text(command,"request_id").equals(text(receipt,"request_id"))&&number(receipt,"quantity")==number(task,"quantity");
        Long released=null;if(valid&&number(receipt,"effect_schema_version")==1)for(Map<String,Object> effect:rows(receipt.get("stock_effects")))if(text(task,"sku_sn").equals(text(effect,"sku_sn")))released=number(effect,"logical_reservation_released");
        if(valid&&number(receipt,"effect_schema_version")==1&&released==null)released=0L;
        List<Map<String,Object>> warehouses=new ArrayList<>();
        for(Map<String,Object> item:items)if(number(item,"cutoff_id")==number(task,"cutoff_id")){
            Map<String,Object> request=obj(item.get("stock_request")),ack=obj(item.get("stock_receipt"));List<Map<String,Object>> replies=rows(ack.get("requests"));boolean confirmed="COMPLETED".equals(text(ack,"state"))&&!replies.isEmpty();Set<String> ids=new HashSet<>();for(Map<String,Object> part:commands(request))ids.add(text(part,"request_id"));
            for(Map<String,Object> part:replies)confirmed&="COMPLETED".equals(text(part,"state"))&&ids.remove(text(part,"request_id"));confirmed&=ids.isEmpty();
            Map<Long,Map<String,Object>> allocations=new HashMap<>();for(Map<String,Object> allocation:rows(request.get("allocations")))allocations.put(number(allocation,"allocation_id"),allocation);
            long expected=0;for(Map<String,Object> allocation:allocations.values())expected+=number(allocation,"quantity");long acknowledged=0;for(Map<String,Object> reply:replies){confirmed&=text(request,"mode").equals(text(reply,"mode"));acknowledged+=number(reply,"quantity");}confirmed&=expected==acknowledged;
            List<Map<String,Object>> all=new ArrayList<>(),own=new ArrayList<>();for(Map<String,Object> source:sources)if(number(source,"shipment_id")==number(item,"shipment_id")&&(allocations.isEmpty()||allocations.containsKey(number(source,"allocation_id")))){Map<String,Object> a=allocations.get(number(source,"allocation_id"));Map<String,Object> row=m("sku_sn",source.get("sku_sn"),"goods_name",source.get("goods_name"),"quantity",a==null?null:a.get("quantity"),"stock_unit",source.get("stock_unit"),"store_code",source.get("store_code"));all.add(row);if(number(source,"order_line_id")==number(task,"order_line_id"))own.add(row);}
            if(!own.isEmpty())warehouses.add(m("shipment_id",item.get("shipment_id"),"shipment_sn",item.get("shipment_sn"),"kind",item.get("dispatch_id")==null?"LOCAL":"WAREHOUSE","warehouse_state",item.get("warehouse_state"),"state",item.get("state"),"last_error",item.get("last_error"),"scope",own,"whole_scope",all,"stock_receipt_confirmed",confirmed,"started_at",item.get("started_at"),"completed_at",item.get("completed_at"),"actor",item.get("operator_name")));
        }
        List<Map<String,Object>> timeline=new ArrayList<>();timeline.add(m("title","取消任务建立","time",task.get("create_time"),"actor","已审核分项任务","state",stopped?"STOPPED":"CONFIRMED","detail","计划取消 "+task.get("quantity")+" "+task.get("stock_unit")));
        for(Map<String,Object> w:warehouses)timeline.add(m("title","LOCAL".equals(text(w,"kind"))?"本地发货安排撤回":"仓库截停原发货安排","time",w.get("completed_at"),"actor",w.get("actor"),"state","CONFIRMED".equals(text(w,"warehouse_state"))?"CONFIRMED":"OUTBOUND".equals(text(w,"warehouse_state"))?"OUTBOUND":"WAITING","detail","完成时间为截单整体记录时间；撤回范围与本退款取消数量分别核对。"));
        timeline.add(m("title","本退款销售需求取消","time",valid?receipt.get("recorded_at"):null,"actor","库存原回执","state",valid?"CONFIRMED":stopped?"STOPPED":command.isEmpty()?"NOT_SENT":"UNKNOWN","detail",valid?"原请求确认取消 "+receipt.get("quantity")+" "+task.get("stock_unit"):"按原请求核对，未使用其他退款的累计取消量"));
        timeline.add(m("title","逻辑预占释放","time",valid?receipt.get("recorded_at"):null,"actor","库存原回执","state",released!=null?"CONFIRMED":"UNKNOWN","detail",released==null?"本次释放数量未记录或原回执待核对；不按任务数量推算":released+" "+task.get("stock_unit")+"；不与分仓撤回数量相加"));
        out.putAll(m("key","cancel-"+task.get("id"),"task_id",task.get("id"),"state",task.get("state"),"quantity",task.get("quantity"),"canceled_quantity",valid?receipt.get("quantity"):command.isEmpty()?0:null,"logical_released_quantity",released,"receipt_confirmed",valid,"inventory_receipt",valid?m("request_id",receipt.get("request_id"),"state",receipt.get("state"),"mode",receipt.get("mode"),"quantity",receipt.get("quantity"),"stock_effects",receipt.get("stock_effects"),"recorded_at",receipt.get("recorded_at")):Collections.emptyMap(),"receipt_request_id",command.get("request_id"),"result_message",task.get("result_message"),"warehouses",warehouses,"timeline",timeline));return out;
    }
    static Map<String,Object> returnResult(Map<String,Object> p,Map<String,Object> source){
        Map<String,Object> out=identity(p),a=obj(p.get("result_json"));long accepted=number(p,"accepted_quantity"),posted=number(p,"posted_quantity"),waived=number(p,"waived_quantity");long good=0,bad=0,postedGood=0,postedBad=0;List<Map<String,Object>> lines=new ArrayList<>();
        for(Map<String,Object> line:rows(a.get("lines"))){good+=number(line,"good_qty");bad+=number(line,"bad_qty");if(number(line,"posted")==1){postedGood+=number(line,"good_qty");postedBad+=number(line,"bad_qty");}lines.add(m("return_sn",line.get("return_sn"),"message_id",line.get("message_id"),"batch_code",line.get("batch_code"),"good_quantity",line.get("good_qty"),"bad_quantity",line.get("bad_qty"),"posted",line.get("posted"),"recorded_at",line.get("create_time")));}
        List<Map<String,Object>> docs=new ArrayList<>(),timeline=new ArrayList<>();timeline.add(m("title","退回安排建立","time",p.get("create_time"),"actor",p.get("actor"),"state","CONFIRMED","detail",p.get("reason")));
        List<Map<String,Object>> rawDocs=a.get("documents") instanceof List?rows(a.get("documents")):a.isEmpty()?Collections.emptyList():Collections.singletonList(a);
        for(Map<String,Object> d:rawDocs){if(text(d,"return_sn").isEmpty())continue;docs.add(m("id",d.get("id"),"return_sn",d.get("return_sn"),"ticket_id",d.get("ticket_id"),"generation",d.get("generation"),"dispatch_state",d.get("dispatch_state"),"receipt_state",d.get("receipt_state"),"cancel_state",d.get("cancel_state"),"external_order",d.get("external_order"),"create_time",d.get("create_time")));timeline.add(m("title","退货入库单生成","time",d.get("create_time"),"actor","仓库对接","state",d.get("dispatch_state"),"detail",d.get("return_sn")));}
        for(Map<String,Object> e:rows(a.get("events")))timeline.add(m("title","仓库回传记录","time",e.get("create_time"),"actor","仓库回传","state",e.get("state"),"detail","原消息 "+e.get("message_id")+"；此时间为回传记录时间，非独立入账完成时间"));
        List<Map<String,Object>> reviews=new ArrayList<>();long reviewQty=0;for(Map<String,Object> e:rows(a.get("reviews")))if("WAIT_REVIEW".equals(text(e,"state"))){reviewQty+=number(e,"quantity");reviews.add(m("id",e.get("id"),"quantity",e.get("quantity"),"reason",e.get("reason"),"create_time",e.get("create_time")));}
        if(source!=null)out.putAll(m("shipment_id",source.get("shipment_id"),"shipment_sn",source.get("shipment_sn"),"original_store_code",source.get("store_code")));
        out.putAll(m("key","return-"+p.get("id"),"plan_id",p.get("id"),"mode",p.get("return_mode"),"state",p.get("state"),"quantity",p.get("quantity"),"accepted_quantity",accepted,"posted_quantity",posted,"remaining_quantity",Math.max(0,number(p,"quantity")-accepted-waived),"unposted_quantity",Math.max(0,accepted-posted),"waived_quantity",waived,"good_quantity",a.get("lines")==null?null:good,"bad_quantity",a.get("lines")==null?null:bad,"posted_good_quantity",a.get("lines")==null?null:postedGood,"posted_bad_quantity",a.get("lines")==null?null:postedBad,
            "pending_review_quantity",reviewQty,"parcel_pending",number(a,"parcel_pending_count")>0,"reviews",reviews,"receipt_lines",lines,"store_code",a.get("store_code")==null?p.get("store_code"):a.get("store_code"),"transport_state",p.get("transport_state"),"return_waybill",p.get("return_waybill"),"parcel_id",a.get("parcel_id"),"parcel_sn",a.get("parcel_sn"),"shared_document",a.get("shared_document"),"documents",docs,"timeline",timeline,"result_message",p.get("last_error"),"auto_dispatch_state",p.get("auto_dispatch_state"),"auto_dispatch_message",p.get("auto_dispatch_message")));
        return out;
    }
}
